add('27_001',2.5,'16:9，武士眼隙与竖直头部的极特写，白眼位于画面右侧，左侧厚重弧面占满大半幅；固定机位，头顶和下颌均在画外。','武士把头沿肩线微抬，狭长黑隙收紧，白眼在其中定住；头侧肌理轻轻绷直，轮廓几乎不动，把蓄力顶点压成一小拍。两段技名旁白依次响起，眼点在第二段落完时短亮一下，外侧气流细线骤然收住。','主体之外只留极窄浅冷灰图形底，深灰压暗层向画边收束。','冷白柔光维持头部体积，眼隙深黑；画边暗层增强凝聚感，晨光只在轮廓留窄暖白线。','低沉聚力声收成很薄的一线，技名读完后短停。',ja=['秘技。','朝立ち。'],tone='技名旁白低沉简短，第一段轻停，第二段重音落定；作为原作排字信息的等值声音承载。',kind='mixed',phase='preparation',node={'叙事阶段':'技名信息揭晓，秘技未实际攻出'},meaning='原格头部极近与技名语义保留；漫画中英排字不作为生成图字，改由日文旁白完整承载。',characters=['鬼头武士'],mode='graphic')
add('27_002',1.5,'16:9，武士头顶与黑色关节长指的特写，头部居画面中央偏左，长指从上方和右侧扣下；固定机位，手主身体留在画外，黑灰图形底向四角压暗。','一只黑色长指手忽然从上方落在头顶，几根指节沿椭圆弧面分开扣住，掌根最后贴稳；武士刚要上提的头被压住，白眼向左下急滑。指尖只先收紧到牢牢控制的位置，头部轮廓凹下一点便停住，方才聚起的气流在两侧断掉。','头与指缝外为黑灰聚光图形底，中央稍浅，四角深黑；实景背景完全被主体与压暗处理覆盖。','上方冷白柔光在黑甲指节留窄亮棱，头部冷灰体积清楚，画边压暗而实体光源保持。','一声轻而清楚的甲指搭触声，聚力声骤然中断，指节随后低低一紧。',phase='contact',node={'叙事阶段':'黑色长指手先扣住武士头顶','武士.状态':'头部被控制，秘技中断','欧铂.揭晓':'只有手入画，身体仍在画外'},meaning='先手后人的接触揭晓保留，此镜只控制头顶，尚未捏碎。',motion='长指自上而下落到头顶再向内扣，头被压住，不抢先展示手主脸。',ground='武士仍站在原地，欧铂的身体和落脚尚未入画。',characters=['鬼头武士','欧铂'],mode='graphic')
